"""Original L&L sales practice content. No customer records or paid curriculum text."""
VERSION = 'll-sales-library-v2'
PROMPT_VERSION = 'll-caller-v3'


def objection(key, title, variants, clarify, response, followup, confirmation=False):
    return {'id': key, 'title': title, 'type': 'policy confirmation' if confirmation else 'sales concern',
            'variants': variants, 'clarify': clarify, 'response': response, 'followup': followup,
            'requires_confirmation': confirmation,
            'principle': 'Acknowledge, clarify the concern, respond with relevant confirmed facts, then check the next step.'}


