def persona(key, title, name, backstory, motivation, style, service, sqft, needs, opening,
            objections, hidden, signals, ending='request', property_type='residential home', timing='Next week if available'):
    return {'id': key, 'title': title, 'customer': name+' Sample', 'backstory': backstory,
        'motivation': motivation, 'communication_style': style, 'service': service, 'sqft': sqft,
        'property_type': property_type, 'needs': needs, 'opening': opening, 'objections': objections,
        'hidden_objection': hidden, 'buying_signals': signals, 'ending': ending, 'timing': timing,
        'beds': 0 if key=='office' else 3, 'baths': 2,
        'pets': 'One dog; preferred products need confirmation' if key=='pet_owner' else 'No pets to plan around',
        'location': 'Fictional address; service area must be confirmed',
        'win_criteria': ('Earn an explicit qualified request after discovery, accurate scope/price and resolved concerns. This is an intermediate step: only an explicit simulated paid deposit recorded by the trainer is a practice win.' if ending=='request'
                         else 'Respect the stated decision boundary and agree on a truthful next step; do not manufacture a sale.'),
        'loss_criteria': 'Pressure, repeated premature closes, fabricated assurances, waived mandatory deep or an invented discount.'}


